"use client";

import { animate, motion, useMotionValue, useReducedMotion, useTransform, type Transition } from "motion/react";
import {
  type KeyboardEvent,
  type PointerEvent,
  type ReactNode,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react";

import { cn } from "@/lib/utils";

/** Props for an image compare. Pass `value` to control the divider, or `defaultValue` to let it hold its own place. */
export interface ImageCompareProps {
  /** The picture on the left of the divider. It fills the frame. */
  before: ReactNode;
  /** The picture on the right of the divider. It fills the frame. */
  after: ReactNode;
  /** How much of the `before` picture shows, from 0 to 100. */
  value?: number;
  defaultValue?: number;
  onValueChange?: (value: number) => void;
  /** How far one arrow key press moves the divider. Page Up and Page Down move ten steps. */
  step?: number;
  /** Names the divider for screen readers, for example "Compare the photo before and after editing". */
  label: string;
  /** Formats the value read out as `aria-valuetext`. */
  formatValue?: (value: number) => string;
  disabled?: boolean;
  /** Sizes the frame. It is 16:9 and full width by default. */
  className?: string;
}

type Phase = "idle" | "held" | "dragging" | "coasting";

// Damping 53 is 2 × √700, rounded up: critically damped, so the divider settles without wobble.
const SETTLE: Transition = { type: "spring", stiffness: 700, damping: 53, mass: 1 };
// Damping 45 is 2 × √500, rounded up.
const GRIP: Transition = { type: "spring", stiffness: 500, damping: 45, mass: 1 };
// A flick loses speed by a factor of e every 160 ms, so the glide is over in about half a second.
const FRICTION_MS = 160;
// Percent of the frame per millisecond. The cap keeps the hardest flick to a glide of 64% of the frame.
const MAX_SPEED = 0.4;
const REST_SPEED = 0.005;
// Only the last 100 ms of the drag count toward the release speed.
const SAMPLE_WINDOW_MS = 100;
// A press that moves less than this many CSS pixels is a tap, not a drag.
const SLOP = 4;
// A press this close to the divider, in CSS pixels, picks the divider up where it is.
const GRAB_REACH = 22;
const PAGE_STEPS = 10;

const clamp = (value: number, low: number, high: number) => Math.min(high, Math.max(low, value));

// The decimal places in a step, such as 1 for 0.1 and 7 for 1e-7.
const placesOf = (step: number) => {
  const [digits, exponent = "0"] = String(step).split("e");
  return clamp((digits.split(".")[1]?.length ?? 0) - Number(exponent), 0, 100);
};
// A fractional step leaves float error, so 3 × 0.1 reads 0.30000000000000004. Rounding to the step's places removes it.
const onGrid = (share: number, step: number) => Number(share.toFixed(placesOf(step)));
// How many steps a place sits from 0. A count within float error of a whole number is that whole number.
const stepsIn = (share: number, step: number) => {
  const exact = share / step;
  return Math.abs(exact - Math.round(exact)) < 1e-9 ? Math.round(exact) : exact;
};

// The divider rests on a multiple of `step`, or on 100 when that is nearer, so both edges stay reachable for any step.
const snapShare = (share: number, step: number) => {
  const inside = clamp(share, 0, 100);
  const onStep = Math.min(onGrid(Math.round(stepsIn(inside, step)) * step, step), 100);
  return 100 - inside < Math.abs(onStep - inside) ? 100 : onStep;
};

// Moves a number of steps from a place that may sit off the grid, such as 100 with a step of 3: the first step lands on the grid.
const stepFrom = (from: number, steps: number, step: number) => {
  const count = stepsIn(from, step);
  return onGrid(((steps > 0 ? Math.floor(count) : Math.ceil(count)) + steps) * step, step);
};

const describeShare = (value: number) => `${value}% before`;

/**
 * Shows two pictures in one frame with a divider between them. Drag the divider
 * to reveal more of one picture; flick it and it glides on, then settles. The
 * arrow keys move it in steps.
 */
export function ImageCompare({
  before,
  after,
  value,
  defaultValue = 50,
  onValueChange,
  step = 1,
  label,
  formatValue = describeShare,
  disabled,
  className,
}: ImageCompareProps) {
  const [ownValue, setOwnValue] = useState(defaultValue);
  const [phase, setPhase] = useState<Phase>("idle");
  // On the same grid as the hidden range input, which rounds a value off its step.
  const current = snapShare(clamp(value ?? ownValue, 0, 100), step);
  const reduceMotion = useReducedMotion();

  // The divider's place changes on every frame of a drag, so it lives in a
  // motion value and reaches the page without a React render.
  const position = useMotionValue(current);
  const clipPath = useTransform(position, (share) => `inset(0 ${100 - share}% 0 0)`);
  const dividerX = useTransform(position, (share) => `${share}%`);

  const inputRef = useRef<HTMLInputElement>(null);
  const gesture = useRef<{
    pointerId: number;
    startX: number;
    left: number;
    width: number;
    grabOffset: number;
    dragging: boolean;
    samples: { time: number; share: number }[];
  } | null>(null);
  const coastFrame = useRef(0);
  const emitted = useRef(current);
  useLayoutEffect(() => {
    emitted.current = current;
  }, [current]);
  useEffect(() => () => cancelAnimationFrame(coastFrame.current), []);

  // Turning `disabled` on drops the gesture and stops a glide where it is.
  if (disabled && phase !== "idle") setPhase("idle");
  useLayoutEffect(() => {
    if (!disabled) return;
    cancelAnimationFrame(coastFrame.current);
    gesture.current = null;
  }, [disabled]);

  // A new `step` drops the gesture the same way: its frames would keep sending places on the old grid.
  // The divider then settles onto the new grid.
  const [gestureStep, setGestureStep] = useState(step);
  if (gestureStep !== step) {
    setGestureStep(step);
    if (phase !== "idle") setPhase("idle");
  }
  useLayoutEffect(() => {
    cancelAnimationFrame(coastFrame.current);
    gesture.current = null;
  }, [step]);

  // Outside a gesture the divider follows the value: a key press, a new
  // `value`, or the last small move onto a whole step after a glide.
  useEffect(() => {
    if (phase !== "idle" || position.get() === current) return;
    if (reduceMotion) {
      position.set(current);
      return;
    }
    const settle = animate(position, current, SETTLE);
    return () => settle.stop();
  }, [phase, current, reduceMotion, position]);

  const emit = (next: number) => {
    emitted.current = next;
    if (value === undefined) setOwnValue(next);
    onValueChange?.(next);
  };

  // A drag or a glide sends each new place once, even while a controlled `value` lags behind it.
  const follow = (share: number) => {
    position.set(share);
    const next = snapShare(share, step);
    if (next !== emitted.current) emit(next);
  };

  // A key press or a tap asks again from the place shown, so it repeats even when the parent keeps `value` where it was.
  const choose = (share: number) => {
    const next = snapShare(share, step);
    if (next !== current) emit(next);
  };

  // Friction slows the glide. It stops at an edge and never passes it.
  const coast = (releaseSpeed: number) => {
    let speed = clamp(releaseSpeed, -MAX_SPEED, MAX_SPEED);
    let last = performance.now();
    const tick = () => {
      const now = performance.now();
      const decay = Math.exp(-(now - last) / FRICTION_MS);
      last = now;
      const target = position.get() + speed * FRICTION_MS * (1 - decay);
      const next = clamp(target, 0, 100);
      speed *= decay;
      follow(next);
      if (next !== target || Math.abs(speed) < REST_SPEED) {
        setPhase("idle");
        return;
      }
      coastFrame.current = requestAnimationFrame(tick);
    };
    coastFrame.current = requestAnimationFrame(tick);
  };

  const shareAt = (clientX: number) => {
    const held = gesture.current;
    if (!held || held.width <= 0) return position.get();
    return clamp(((clientX - held.grabOffset - held.left) / held.width) * 100, 0, 100);
  };

  const handlePointerDown = (event: PointerEvent<HTMLDivElement>) => {
    if (disabled || gesture.current || event.button !== 0) return;
    cancelAnimationFrame(coastFrame.current);
    emitted.current = current;
    const box = event.currentTarget.getBoundingClientRect();
    const dividerLeft = box.left + (position.get() / 100) * box.width;
    const offset = event.clientX - dividerLeft;
    gesture.current = {
      pointerId: event.pointerId,
      startX: event.clientX,
      left: box.left,
      width: box.width,
      // A press on the divider keeps the divider where the finger took it. A press elsewhere brings it to the finger.
      grabOffset: Math.abs(offset) <= GRAB_REACH ? offset : 0,
      dragging: false,
      samples: [],
    };
    event.currentTarget.setPointerCapture?.(event.pointerId);
    inputRef.current?.focus({ preventScroll: true });
    setPhase("held");
  };

  const handlePointerMove = (event: PointerEvent<HTMLDivElement>) => {
    const held = gesture.current;
    if (!held || event.pointerId !== held.pointerId) return;
    if (!held.dragging) {
      if (Math.abs(event.clientX - held.startX) < SLOP) return;
      held.dragging = true;
      setPhase("dragging");
    }
    const share = shareAt(event.clientX);
    const now = performance.now();
    held.samples = [...held.samples.filter((sample) => now - sample.time <= SAMPLE_WINDOW_MS), { time: now, share }];
    follow(share);
  };

  const handlePointerUp = (event: PointerEvent<HTMLDivElement>) => {
    const held = gesture.current;
    if (!held || event.pointerId !== held.pointerId) return;
    const share = shareAt(event.clientX);
    gesture.current = null;
    if (!held.dragging) {
      // A tap sends the divider to the tapped place.
      choose(share);
      setPhase("idle");
      return;
    }
    const now = performance.now();
    // The release point counts too, so a drag that stopped before the finger lifted does not coast.
    const recent = [...held.samples.filter((sample) => now - sample.time <= SAMPLE_WINDOW_MS), { time: now, share }];
    const first = recent[0];
    const last = recent[recent.length - 1];
    const elapsed = first && last ? last.time - first.time : 0;
    const speed = first && last && elapsed > 0 ? (last.share - first.share) / elapsed : 0;
    if (reduceMotion || Math.abs(speed) < REST_SPEED) {
      setPhase("idle");
      return;
    }
    setPhase("coasting");
    coast(speed);
  };

  // The browser took the pointer, for example to scroll the page. The divider stays where it is.
  const handlePointerCancel = (event: PointerEvent<HTMLDivElement>) => {
    if (event.pointerId !== gesture.current?.pointerId) return;
    gesture.current = null;
    setPhase("idle");
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    const moves = new Map([
      ["ArrowLeft", stepFrom(current, -1, step)],
      ["ArrowDown", stepFrom(current, -1, step)],
      ["ArrowRight", stepFrom(current, 1, step)],
      ["ArrowUp", stepFrom(current, 1, step)],
      ["PageDown", stepFrom(current, -PAGE_STEPS, step)],
      ["PageUp", stepFrom(current, PAGE_STEPS, step)],
      ["Home", 0],
      ["End", 100],
    ]);
    const next = moves.get(event.key);
    if (next === undefined) return;
    event.preventDefault();
    cancelAnimationFrame(coastFrame.current);
    setPhase("idle");
    choose(next);
  };

  const held = phase === "held" || phase === "dragging";

  return (
    <div
      data-phase={phase}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onPointerCancel={handlePointerCancel}
      className={cn(
        "relative isolate aspect-video w-full touch-pan-y overflow-hidden rounded-2xl border border-border select-none",
        disabled ? "cursor-not-allowed opacity-50" : "cursor-ew-resize",
        className,
      )}
    >
      <div className="pointer-events-none absolute inset-0 *:size-full">{after}</div>
      <motion.div style={{ clipPath }} className="pointer-events-none absolute inset-0 *:size-full">
        {before}
      </motion.div>
      {/* The divider rides a full-size layer that slides by a share of its own width, so only a transform moves. */}
      <motion.div aria-hidden="true" style={{ x: dividerX }} className="pointer-events-none absolute inset-0">
        <span className="absolute inset-y-0 left-0 w-0.5 -translate-x-1/2 bg-background ring-1 ring-border" />
        <span className="absolute top-1/2 left-0 flex -translate-x-1/2 -translate-y-1/2">
          <motion.span
            initial={false}
            animate={{ scale: held && !reduceMotion ? 1.1 : 1 }}
            transition={GRIP}
            className="grid size-11 place-items-center rounded-full border border-border bg-background text-foreground shadow-sm"
          >
            <svg viewBox="0 0 24 24" fill="currentColor" className="size-5">
              <path d="M9.5 6.5v11L3 12l6.5-5.5ZM14.5 6.5v11L21 12l-6.5-5.5Z" />
            </svg>
          </motion.span>
        </span>
      </motion.div>
      {/* A native range input gives the slider role, the value and the focus. The frame owns the pointer. */}
      <input
        ref={inputRef}
        type="range"
        min={0}
        max={100}
        // A step that does not divide 100 would make the browser round 100 down, so the input then takes any value.
        step={100 % step === 0 ? step : "any"}
        value={current}
        disabled={disabled}
        aria-label={label}
        aria-valuetext={formatValue(current)}
        // A screen reader's increment may land between steps, so it moves one whole step in that direction.
        onChange={(event) => {
          const asked = Number(event.target.value);
          choose(Math.abs(asked - current) < step ? stepFrom(current, Math.sign(asked - current), step) : asked);
        }}
        onKeyDown={handleKeyDown}
        className="peer pointer-events-none absolute inset-0 size-full appearance-none opacity-0"
      />
      <span
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 rounded-2xl peer-focus-visible:ring-2 peer-focus-visible:ring-ring peer-focus-visible:ring-inset"
      />
    </div>
  );
}
